const DOT = "M790.4,104.9 L790.5,105.0";

/**
 * EXACT LETTER RHYTHM BOUNDS:
 * 1. First 3 letters ("y", "o", "u") take the EXACT SAME amount of time (15.0% each = 45% total).
 *    - Letter 'y': strokes 0 and 1 -> from 0.0000 to 0.1500 (duration: 15.0%)
 *    - Letter 'o': stroke 2        -> from 0.1500 to 0.3000 (duration: 15.0%)
 *    - Letter 'u': stroke 3        -> from 0.3000 to 0.4500 (duration: 15.0%)
 * 2. Middle letters ("d", "e", "c", "i") are a BIT FAST (25.0% total):
 *    - Letter 'd': strokes 4 and 5 -> from 0.4500 to 0.5458 (duration: 9.6%)
 *    - Letter 'e': stroke 6        -> from 0.5458 to 0.6042 (duration: 5.8%)
 *    - Letter 'c': stroke 7        -> from 0.6042 to 0.6542 (duration: 5.0%)
 *    - Letter 'i': stroke 8        -> from 0.6542 to 0.7000 (duration: 4.6%)
 * 3. End letters ("d", "e", dot) are a LITTLE SLOW (30.0% total):
 *    - Letter 'd': strokes 9 and 10-> from 0.7000 to 0.8292 (duration: 12.9%)
 *    - Letter 'e': stroke 11       -> from 0.8292 to 0.9250 (duration: 9.6%)
 *    - Dot on 'i': dot             -> from 0.9250 to 1.0000 (duration: 7.5%)
 */
const STROKE_BOUNDS = [
  0.0,      // 0: start of 'y' (stroke 0)
  0.04763,  // 1: 'y' branch end -> stroke 1 start
  0.15000,  // 2: 'y' tail end -> start of 'o' (stroke 2) [0.1500 total for 'y']
  0.30000,  // 3: 'o' end -> start of 'u' (stroke 3)      [0.1500 total for 'o']
  0.45000,  // 4: 'u' end -> start of 'd' (stroke 4)      [0.1500 total for 'u']
  0.51842,  // 5: 'd1' ascender end -> stroke 5 start
  0.54583,  // 6: 'd1' stem end -> start of 'e' (stroke 6)
  0.60417,  // 7: 'e1' end -> start of 'c' (stroke 7)
  0.65417,  // 8: 'c' end -> start of 'i' (stroke 8)
  0.70000,  // 9: 'i' stem end -> start of second 'd' (stroke 9)
  0.79221,  // 10: 'd2' ascender end -> stroke 10 start
  0.82917,  // 11: 'd2' stem end -> start of second 'e' (stroke 11)
  0.92500,  // 12: 'e2' end -> start of dot
  1.00000,  // 13: dot end
];

const DOT_START = 0.92500;
const DOT_END = 1.00000;

function StrokePath({
  d,
  a,
  b,
  progress,
  width,
}: {
  d: string;
  a: number;
  b: number;
  progress: any;
  width: number;
}) {
  const length = useTransform(progress, [a, b], [0, 1], { clamp: true });
  const opacity = useTransform(progress, (v: number) => (v > a ? 1 : 0));

  return (
    <motion.path
      d={d}
      style={{ pathLength: length, opacity }}
      strokeWidth={width}
      strokeLinecap="round"
      strokeLinejoin="round"
    />
  );
}

export const YoudecideIntro: React.FC<YoudecideIntroProps> = ({
  onComplete,
  duration = 4.8,
}) => {
  const [stage, setStage] = useState<'drawing' | 'drawn' | 'exiting' | 'done'>('drawing');
  const progress = useMotionValue(0);

  useEffect(() => {
    progress.set(0);

    let controls: any;
    let holdTimer: ReturnType<typeof setTimeout>;
    let doneTimer: ReturnType<typeof setTimeout>;

    // 1. A 300ms breath on initial mount ensures the browser finishes initial layout,
    //    hydration, and WebGL compilation so the user clearly sees the first pen stroke of "y"
    //    without any dropped frames or sudden jumps.
    const startTimer = setTimeout(() => {
      controls = animate(progress, 1, {
        duration,
        // Linear progress directly routes our calculated letter timings:
        // first 3 letters equal time, middle letters bit fast, end letters little slow!
        ease: 'linear',
      });

      controls.then(() => {
        setStage('drawn');

        // Hold complete glowing cursive signature for 450ms
        holdTimer = setTimeout(() => {
          setStage('exiting');
        }, 450);

        // Complete bottom-to-top curtain lift and unmount
        doneTimer = setTimeout(() => {
          setStage('done');
          onComplete?.();
        }, 450 + 850);
      });
    }, 300);

    return () => {
      clearTimeout(startTimer);
      if (controls) controls.stop();
      clearTimeout(holdTimer);
      clearTimeout(doneTimer);
    };
  }, [duration, onComplete, progress]);

  const dotProgress = useTransform(progress, [DOT_START, DOT_END], [0, 1], { clamp: true });
  const dotOpacity = useTransform(progress, (v: number) => (v > DOT_START ? 1 : 0));

  if (stage === 'done') return null;

  return (
    <AnimatePresence>
      {stage !== 'done' && (
        <motion.div
          key="youdecide-intro"
          initial={{ y: 0 }}
          animate={{
            y: stage === 'exiting' ? '-100%' : 0,
          }}
          transition={{
            duration: 0.82,
            ease: [0.76, 0, 0.24, 1], // Cinematic smooth bottom-to-top curtain lift
          }}
          onClick={() => {
            if (stage !== 'exiting') setStage('exiting');
          }}
          style={{
            position: 'fixed',
            inset: 0,
            zIndex: 99999,
            backgroundColor: '#040711',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            overflow: 'hidden',
            pointerEvents: stage === 'exiting' ? 'none' : 'auto',
            cursor: stage === 'exiting' ? 'default' : 'pointer',
          }}
        >
          {/* Luminous Aurora Atmosphere Overlays */}
          <div
            style={{
              position: 'absolute',
              inset: 0,
              background:
                'radial-gradient(ellipse 90% 60% at 50% 35%, rgba(38, 208, 206, 0.22) 0%, rgba(25, 32, 240, 0.18) 40%, rgba(4, 7, 17, 0.95) 80%, #040711 100%)',
              pointerEvents: 'none',
            }}
          />

          {/* Vertical Aurora Rays / Luminous Sheen */}
          <div
            style={{
              position: 'absolute',
              top: '-25%',
              left: '15%',
              right: '15%',
              height: '85%',
              background:
                'radial-gradient(ellipse at top, rgba(97, 238, 224, 0.16) 0%, rgba(25, 32, 240, 0.12) 50%, transparent 80%)',
              filter: 'blur(45px)',
              pointerEvents: 'none',
            }}
          />

          {/* Ambient ground shimmer glow */}
          <div
            style={{
              position: 'absolute',
              bottom: 0,
              left: 0,
              right: 0,
              height: '35%',
              background:
                'linear-gradient(to top, rgba(25, 32, 240, 0.14) 0%, transparent 100%)',
              pointerEvents: 'none',
            }}
          />

          {/* Central Animated "youdecide" Cursive Hand-Writing SVG */}
          <motion.div
            initial={{ opacity: 0, scale: 0.96 }}
            animate={{
              opacity: stage === 'exiting' ? 0.35 : 1,
              scale: stage === 'exiting' ? 1.03 : 1,
            }}
            transition={{ duration: 0.5, ease: 'easeOut' }}
            style={{
              position: 'relative',
              zIndex: 10,
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              justifyContent: 'center',
              width: '100%',
              maxWidth: '760px',
              padding: '0 28px',
              boxSizing: 'border-box',
            }}
          >
            <svg
              viewBox={`0 0 ${VIEWBOX_W} ${VIEWBOX_H}`}
              fill="none"
              stroke="#FFFFFF"
              role="img"
              aria-label="youdecide"
              style={{
                width: '100%',
                height: 'auto',
                display: 'block',
                overflow: 'visible',
                filter:
                  stage === 'drawn' || stage === 'exiting'
                    ? 'drop-shadow(0 0 22px rgba(255, 255, 255, 0.55)) drop-shadow(0 0 45px rgba(64, 224, 208, 0.35))'
                    : 'drop-shadow(0 0 12px rgba(255, 255, 255, 0.3))',
                transition: 'filter 0.4s ease',
              }}
            >
              <g className="yd-ink">
                {STROKES.map((d, i) => (
                  <StrokePath
                    key={i}
                    d={d}
                    a={STROKE_BOUNDS[i]}
                    b={STROKE_BOUNDS[i + 1]}
                    progress={progress}
                    width={15}
                  />
                ))}

                {/* The "i" dot */}
                <motion.path
                  d={DOT}
                  style={{
                    pathLength: dotProgress,
                    opacity: dotOpacity,
                  }}
                  strokeWidth={21}
                  strokeLinecap="round"
                />
              </g>
            </svg>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

export default YoudecideIntro;
